REPORT_ROOT = Path('/var/lib/portal-research-fund-skill-update-project-type-20261105-r1')
BASE = ['kubectl', '--kubeconfig=/etc/kubernetes/admin.conf', '--request-timeout=15s', '-n', 'deer-flow']
STARTED = 0
